mapper.select:
SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND YEAR(trade_date) = #{year}
ORDER BY trade_date ASC
LIMIT 1

SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND YEAR(trade_date) = #{year}
ORDER BY trade_date DESC
LIMIT 1

SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY trade_date ASC

SELECT
    d.stock_code AS stockCode,
    s.stock_name AS stockName,
    s.industry,
    d.close_price AS price,
    d.change_percent AS changePct,
    d.volume
FROM stock_daily d
JOIN stock s ON d.stock_code = s.stock_code
WHERE d.trade_date = (
    SELECT MAX(trade_date) FROM stock_daily
)

    AND s.industry = #{industry}


    AND d.close_price >= #{minPrice}


    AND d.close_price <= #{maxPrice}


    AND d.change_percent >= #{minChange}

ORDER BY d.change_percent DESC
LIMIT #{limit}
